94	  /// Parses overrides from the raw JSON "overrides" object in package.json.
95	  ///
96	  /// `root_deps` should contain all direct dependencies of the root package
97	  /// (merged from `dependencies`, `devDependencies`, etc.) mapping bare
98	  /// specifier to version string. This is used to resolve `$pkg` references.
99	  pub fn from_value(
100	    value: serde_json::Value,
101	    root_deps: &HashMap<PackageName, StackString>,
102	  ) -> Result<Self, NpmOverridesError> {
103	    match value {
104	      serde_json::Value::Object(map) => {
105	        let rules = parse_override_rules(&map, root_deps)?;
106	        Ok(Self { rules })
107	      }
108	      serde_json::Value::Null => Ok(Self::default()),
109	      _ => Err(NpmOverridesError::InvalidTopLevelType),
110	    }
111	  }
