117	  /// Computes the active overrides for a child node in the dependency tree.
118	  ///
119	  /// When descending into `child_name@child_version`:
120	  /// - Rules that target `child_name` and whose selector matches: their
121	  ///   `children` become active for this subtree. Scoped children are placed
122	  ///   before passthrough rules so they take precedence in lookups.
123	  /// - Rules that target other packages (either simple or scoped): pass
124	  ///   through unchanged so they can match deeper descendants.
125	  pub fn for_child(
126	    self: &Rc<Self>,
127	    child_name: &PackageName,
128	    child_version: &Version,
129	  ) -> Rc<Self> {
130	    if self.rules.is_empty() {
131	      return self.clone();
132	    }
133	
134	    let mut scoped_children: Vec<Arc<NpmOverrideRule>> = Vec::new();
135	    let mut passthrough_rules: Vec<Arc<NpmOverrideRule>> = Vec::new();
136	    let mut changed = false;
137	
138	    for rule in self.rules.iter() {
139	      if rule.name == *child_name {
140	        let selector_matches = match &rule.selector {
141	          Some(selector) => selector.matches(child_version),
142	          None => true,
143	        };
144	
145	        if selector_matches && !rule.children.is_empty() {
146	          // this rule targets the current child and matches; activate its
147	          // nested overrides for this subtree
148	          scoped_children.extend(rule.children.iter().cloned());
149	        }
150	        if rule.children.is_empty()
151	          || (rule.selector.is_some() && !selector_matches)
152	        {
153	          // pass through when: the rule is a simple childless override
154	          // (so it keeps applying deeper), OR the rule has a selector
155	          // that didn't match this version (so it can still match a
156	          // deeper occurrence at a different version)
157	          passthrough_rules.push(rule.clone());
158	        }
159	        changed = true;
160	      } else {
161	        // this rule targets a different package — keep it active for
162	        // deeper descendants
163	        passthrough_rules.push(rule.clone());
164	      }
165	    }
166	
167	    if !changed {
168	      self.clone()
169	    } else {
170	      // scoped children first so they take precedence over passthrough rules
171	      scoped_children.extend(passthrough_rules);
172	      Rc::new(Self {
173	        rules: scoped_children,
174	      })
175	    }
176	  }
